/** Teaching comes first; real-item help stays one clear click away.
 * The landing uses lightweight vector art. Explore owns the live 3D world. */
import {mountActivityFinder} from './activities.js';
import {heroArt,deviceArt} from './tutorial-art.js';

const arrows='<span aria-hidden="true">↗</span>';
export const HOME_QUESTIONS=Object.freeze([
  {title:'What should we do when it breaks?',copy:'Look for clues: does it still work, can it be repaired safely, or has it reached the end of its life?'},
  {title:'Where should it go?',copy:'To a repairer, to someone who needs it, or to a special e-waste drop-off. Never the household bin.'},
  {title:'Why does it matter?',copy:'Appliances hold metals and plastics that can be used again, and old batteries can be dangerous in rubbish trucks.'},
].map(question=>Object.freeze(question)));
const chapters=[
  [0,'A better story begins'],[13.24,'Two ways to begin'],[26.144,'Explore a device'],[37.848,'Learn through a choice'],[53.176,'Start with your item'],[66.176,'Ask important questions'],[80.064,'Find the next step'],[92.064,'A habit worth sharing'],
];
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountLanding(host,{signal,filmUrl='/film.html',assetRoot='/prototypes/i3-family-landing/assets/'}={}) {
  if(signal?.aborted)return()=>{};
  const win=host.ownerDocument.defaultView,controller=new win.AbortController();
  host.innerHTML=`<div class="ffh-home">
    <div class="ffh-hero-band"><section class="ffh-hero ffh-wrap" aria-labelledby="ffh-title"><div class="ffh-hero-copy"><p class="ffh-kicker"><span></span> For parents and children aged 7–12</p><h1 id="ffh-title">When something breaks,<br><span>teach them what<br class="ffh-wide-break"> comes next.</span></h1><p class="ffh-intro">FixForward helps you and your child learn about e-waste together: what to do when an appliance stops working, where it should go, and why it matters.</p><div class="ffh-hero-actions"><a class="ffh-button ffh-primary" href="#learn">Learn together ${arrows}</a><a class="ffh-button ffh-secondary" href="#decide">Get help with an item ${arrows}</a></div><p class="ffh-note">No account needed <span>·</span> Play at your pace <span>·</span> Learn side by side</p><button type="button" class="ffh-watch" data-film-open><span class="ffh-small-play" aria-hidden="true">▶</span> See our story <span>1:57</span></button></div><div class="ffh-hero-visual">${heroArt()}<p class="ffh-art-caption">A small question. A better next step.</p></div></section></div>
    <div class="ffh-principles ffh-wrap"><span><b aria-hidden="true">01</b> Notice a clue</span><i aria-hidden="true">→</i><span><b aria-hidden="true">02</b> Try a next step</span><i aria-hidden="true">→</i><span><b aria-hidden="true">03</b> Talk about why</span></div>
    <section class="ffh-wrap ffh-section" aria-labelledby="ffh-start-title"><div class="ffh-section-heading"><div><p class="ffh-kicker">YOUR REASON TO BE HERE</p><h2 id="ffh-start-title">A useful place to start.</h2></div><p>A little curiosity or a real-life question.<br>Choose what your family needs today.</p></div><div class="ffh-start-grid"><article class="ffh-start-card ffh-learning" data-ffh-reveal><span class="ffh-start-icon" aria-hidden="true">✦</span><span class="ffh-label">LET’S LEARN TOGETHER</span><h3>“I want to teach my child.”</h3><p>Choose a game. Try a little practice first. Discover how everyday choices can give useful things a longer life.</p><a href="#learn">Find a learning game ${arrows}</a><span class="ffh-card-index" aria-hidden="true">01</span></article><article class="ffh-start-card" data-ffh-reveal><span class="ffh-start-icon" aria-hidden="true">↗</span><span class="ffh-label">WITH AN ADULT</span><h3>“Something stopped working.”</h3><p>Start with the item. Understand the questions to ask and explore repair, reuse or appropriate recycling help.</p><a href="#decide">Find a next step ${arrows}</a><span class="ffh-card-index" aria-hidden="true">02</span></article></div></section>
    <section class="ffh-questions-band" aria-labelledby="ffh-questions-title"><div class="ffh-wrap"><h2 id="ffh-questions-title">Three questions your child will be able to answer</h2><ol class="ffh-questions">${HOME_QUESTIONS.map((question,index)=>`<li data-ffh-reveal><span class="ffh-question-number" aria-hidden="true">${index+1}</span><h3>${question.title}</h3><p>${question.copy}</p></li>`).join('')}</ol></div></section>
    <section class="ffh-wrap ffh-section ffh-activities" aria-labelledby="ffh-activities-title"><div class="ffh-section-heading"><h2 id="ffh-activities-title">Pick an activity for your child</h2><a class="ffh-text-link" href="#learn">See all five games <span aria-hidden="true">→</span></a></div><div data-home-finder></div><p class="ffh-activity-note">Suggested ages are a guide. Younger children can join in with a grown-up reading along.</p></section>
    <section class="ffh-wrap ffh-explore" aria-labelledby="ffh-explore-title" data-ffh-reveal><div class="ffh-explore-picture"><span class="ffh-label">A PICTURE OF POSSIBILITY</span><div class="ffh-explore-device">${deviceArt('kettle')}</div><span class="ffh-part ffh-part-one">What does this part do?</span><span class="ffh-part ffh-part-two">How can it last longer?</span><span class="ffh-orbit" aria-hidden="true"></span></div><div class="ffh-explore-copy"><p class="ffh-kicker">FROM “WHAT’S THAT?” TO “NOW I GET IT.”</p><h2 id="ffh-explore-title">Every device has<br>an inside story.</h2><p>Visit Explore to rotate a digital appliance, look at its parts and discover its story. Turn a familiar object into a conversation.</p><a class="ffh-button ffh-primary" href="#explore?view=world">Enter Explore ${arrows}</a><p class="ffh-small">Explore on screen. Keep real appliances closed.</p></div></section>
    <section class="ffh-wrap ffh-section ffh-parent-section" aria-labelledby="ffh-parent-title"><div class="ffh-parent-copy"><p class="ffh-kicker">FOR THE GROWN-UP BESIDE THEM</p><h2 id="ffh-parent-title">See the thinking<br>behind the choice.</h2><p>A score is a starting point. Look for the clue your child noticed, a choice they tried again, or an idea to practise together.</p><p>Where a game saves learning feedback, the record stays in this browser. No child’s name or account is needed.</p><a class="ffh-text-link" href="#parents">Find our learning feedback ${arrows}</a></div><div class="ffh-conversation" data-ffh-reveal><p class="ffh-label">AN EXAMPLE CONVERSATION</p><div class="ffh-speech ffh-child"><span aria-hidden="true">?</span><p>“I thought everything old should be recycled.”</p></div><div class="ffh-speech ffh-adult"><span aria-hidden="true">↗</span><p>“This one still works. Who could use it next?”</p></div><div class="ffh-takeaway"><span aria-hidden="true">✓</span><p><strong>A clue to remember</strong>Old does not always mean finished.</p></div></div></section>
    <section class="ffh-wrap ffh-film" aria-labelledby="ffh-film-title" data-ffh-reveal><div class="ffh-film-poster"><div class="ffh-film-art">${heroArt()}</div><button type="button" data-film-open aria-label="Play the narrated FixForward product film"><span aria-hidden="true">▶</span></button><span class="ffh-film-time">1:57 · NARRATED STORY</span></div><div class="ffh-film-copy"><p class="ffh-kicker">THE BIG PICTURE, IN UNDER TWO MINUTES</p><h2 id="ffh-film-title">One family.<br>A little curiosity.<br>A different next step.</h2><p>See how learning and real-item help fit together. Then choose your own place to begin.</p><button type="button" class="ffh-text-link" data-film-open>Watch our story <span aria-hidden="true">▶</span></button><p class="ffh-small">Narration and captions. Sound starts only when you play.</p><details class="ffh-transcript"><summary>Prefer to read the story?</summary><p>A kettle stops working. A laptop sits forgotten. A child asks: does this have to become rubbish? FixForward helps a family explore what devices do and why the next step depends on the clues. A working, checked laptop could find a new home. A real faulty item needs an adult to check warning signs and seek appropriate advice. Repair when suitable, reuse when safe and wanted, or find an accepted e-waste service. The useful habit is simple: find out before throwing it away.</p><a href="${escape(assetRoot)}product-film-transcript.txt">Read the full film transcript ↗</a></details></div></section>
    <section class="ffh-wrap ffh-section ffh-faq" aria-labelledby="ffh-faq-title"><div><p class="ffh-kicker">GOOD QUESTIONS</p><h2 id="ffh-faq-title">Made for families.<br>Useful for real life.</h2></div><div class="ffh-faq-list"><details><summary>Is this for parents or children?</summary><p>Both, together. Children can explore the games while a grown-up helps with reading and conversation. Adults can also go straight to help with a real item.</p></details><details><summary>Which game should we start with?</summary><p>Try Fix-it Station first: follow a clue and choose the item’s next step. Each game has a “How to play” practice so you can try the idea before starting.</p></details><details><summary>Will my child learn to repair real electrical items?</summary><p>The activities teach care, decisions and when to ask for help. They use pretend objects. Real appliances stay closed; an adult follows the maker’s guidance and arranges qualified help when needed.</p></details><details><summary>Do we need an account or a photo?</summary><p>No account is needed for these learning games. Photos are not needed to play. For real-item help, choosing a category manually remains an option.</p></details><details><summary>Can a photo prove an appliance is safe?</summary><p>No. Where a photo helper is available, it suggests an item category. It cannot diagnose a fault, confirm safety or replace model and recall checks.</p></details></div></section>
    <section class="ffh-wrap ffh-last"><div><p class="ffh-kicker">START WITH ONE SMALL DISCOVERY</p><h2>What could happen next?</h2></div><a class="ffh-button ffh-primary" href="#learn">Let’s find out together ${arrows}</a></section>
    <dialog class="ffh-film-dialog" aria-labelledby="ffh-dialog-title"><div class="ffh-film-dialog-top"><div><p class="ffh-kicker">FIXFORWARD · 1:57</p><h2 id="ffh-dialog-title">A better next step</h2></div><button type="button" data-film-close aria-label="Close product film">×</button></div><video controls playsinline preload="none" aria-label="Narrated FixForward product film"><source src="${escape(assetRoot)}fixforward-product-film.mp4" type="video/mp4"><track kind="captions" src="${escape(assetRoot)}fixforward-product-film.vtt" srclang="en" label="English captions">Read the story on this page if video is unavailable.</video><div class="ffh-film-chapters" aria-label="Film chapters">${chapters.map(([seconds,title])=>`<button type="button" data-film-chapter="${seconds}"><span>${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}</span>${title}</button>`).join('')}</div><p class="ffh-film-error" role="status" hidden>The film could not start. Try the video controls or open the full player.</p><a class="ffh-text-link" href="${escape(filmUrl)}">Open the full player ↗</a></dialog>
  </div>`;
  const stopFinder=mountActivityFinder(host.querySelector('[data-home-finder]'),{signal:controller.signal,home:true});
  const dialog=host.querySelector('dialog'),video=dialog.querySelector('video');
  let opener=null,observer,disposed=false;
  const play=()=>{try{const promise=video.play();promise?.catch(()=>{if(!disposed)host.querySelector('.ffh-film-error').hidden=false;});}catch{host.querySelector('.ffh-film-error').hidden=false;}};
  function openFilm(button){opener=button;host.querySelector('.ffh-film-error').hidden=true;dialog.showModal();dialog.querySelector('[data-film-close]').focus();play();}
  host.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||!host.contains(button))return;if(button.hasAttribute('data-film-open'))openFilm(button);if(button.hasAttribute('data-film-close')){video.pause();dialog.close();}if(button.hasAttribute('data-film-chapter')){video.currentTime=Number(button.dataset.filmChapter);play();}},{signal:controller.signal});
  dialog.addEventListener('close',()=>{video.pause();opener?.isConnected&&opener.focus();},{signal:controller.signal});
  dialog.addEventListener('cancel',()=>video.pause(),{signal:controller.signal});
  video.addEventListener('error',()=>{host.querySelector('.ffh-film-error').hidden=false;},{signal:controller.signal});
  // Sections are visible before enhancement and when reduced motion is enabled.
  if(win.IntersectionObserver&&!win.matchMedia?.('(prefers-reduced-motion: reduce)').matches){observer=new win.IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('ffh-revealed');observer.unobserve(entry.target);}}),{threshold:.15});host.querySelectorAll('[data-ffh-reveal]').forEach(element=>observer.observe(element));}
  const cleanup=()=>{if(disposed)return;disposed=true;observer?.disconnect();stopFinder();video.pause();if(dialog.open)dialog.close();controller.abort();signal?.removeEventListener('abort',cleanup);};signal?.addEventListener('abort',cleanup,{once:true});return cleanup;
}
